using System;using System.IO;using System.Linq;using System.Reflection;using System.Text;using UnityEditor;using UnityEngine;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public static class StudioCreaseWireValidation {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;static StringBuilder report=new StringBuilder();static int checks;
 static void Check(bool ok,string m){if(!ok)throw new Exception(m);checks++;}
 static Color32[] Render(StudioModelEditor ed,SceneView view,RenderTexture rt,Material solid,bool xray,bool cover){var old=RenderTexture.active;RenderTexture.active=rt;GL.PushMatrix();try{GL.Viewport(new Rect(0,0,512,512));GL.Clear(true,true,Color.white);GL.LoadProjectionMatrix(view.camera.projectionMatrix);GL.modelview=view.camera.worldToCameraMatrix;solid.SetPass(0);Graphics.DrawMeshNow(ed.Document.nodes[0].mesh,Matrix4x4.identity);if(cover){var mesh=StudioModelDocument.BuildPrimitive(PrimitiveType.Quad);solid.SetPass(0);Graphics.DrawMeshNow(mesh,Matrix4x4.TRS(view.camera.transform.position+view.camera.transform.forward,view.camera.transform.rotation,Vector3.one*20));Object.DestroyImmediate(mesh);}typeof(StudioModelEditor).GetField("displayXray",F).SetValue(ed,xray);typeof(StudioModelEditor).GetMethod("DrawVisibleObjectWireframes",F).Invoke(ed,new object[]{view.camera});var t=new Texture2D(512,512,TextureFormat.RGBA32,false);try{t.ReadPixels(new Rect(0,0,512,512),0,0);t.Apply();return t.GetPixels32();}finally{Object.DestroyImmediate(t);}}finally{GL.PopMatrix();RenderTexture.active=old;}}
 static int Ink(Color32[] p)=>p.Count(c=>c.r<235&&c.g<235&&c.b<235);
 static void Save(Color32[] p,string name){var t=new Texture2D(512,512,TextureFormat.RGBA32,false);t.SetPixels32(p);t.Apply();File.WriteAllBytes(Path.GetFullPath(Path.Combine(Application.dataPath,"../../crease-wire-"+name+".png")),t.EncodeToPNG());Object.DestroyImmediate(t);}
 public static void Run(){int exit=0;var view=ScriptableObject.CreateInstance<SceneView>();var rt=new RenderTexture(512,512,24);rt.Create();view.camera.targetTexture=rt;view.camera.pixelRect=new Rect(0,0,512,512);view.camera.nearClipPlane=.03f;view.camera.farClipPlane=1000;view.camera.fieldOfView=60;view.camera.orthographicSize=1.5f;var solid=new Material(Shader.Find("Hidden/StudioValidationSolid"));try{StudioSettings.Current.hideObjectWireframe=false;foreach(bool ortho in new[]{false,true})foreach(float slope in new[]{.1f,1f,2.9f,2.99f,3f,3.1f,10f,100f})foreach(float tilt in new[]{0f,2f,-2f}){view.camera.orthographic=ortho;view.camera.transform.position=new Vector3(0,0,-3);view.camera.transform.rotation=Quaternion.Euler(tilt,0,0);var mesh=new Mesh();mesh.vertices=new[]{new Vector3(-1,0,0),new Vector3(1,0,0),new Vector3(-1,1,-slope),new Vector3(1,1,-slope),new Vector3(-1,-1,-slope),new Vector3(1,-1,-slope)};mesh.triangles=new[]{0,2,3,0,3,1,0,1,5,0,5,4};var doc=ScriptableObject.CreateInstance<StudioModelDocument>();doc.nodes.Add(new StudioModelDocument.Node{mesh=mesh,cutTriangles=mesh.triangles,cutPolygons=new[]{0,4,0,2,3,1,0,4,0,1,5,4}});using(var ed=new StudioModelEditor(()=>{})){ed.Load(doc);var visible=Render(ed,view,rt,solid,false,false);var reference=Render(ed,view,rt,solid,true,false);var center=view.camera.WorldToScreenPoint(Vector3.zero);int y=Mathf.RoundToInt(center.y);int InkCenter(Color32[] p)=>Enumerable.Range(y-3,7).Sum(row=>Enumerable.Range(190,130).Count(x=>{var c=p[row*512+x];return c.r<235&&c.g<235&&c.b<235;}));int a=InkCenter(visible),b=InkCenter(reference);report.AppendLine($"ortho={ortho} slope={slope} tilt={tilt} visible={a} xray={b}");if(slope==3.1f&&tilt==0&&!ortho){Save(visible,"crease");Save(reference,"xray");}Check(b>100,"Reference missing crease");Check(a>=b*.8f,"Own concave faces hide crease: "+report.ToString().Split('\n').Reverse().Skip(1).First());Check(InkCenter(Render(ed,view,rt,solid,false,true))==0,"Crease leaks through unrelated foreground");int uploads=ed.WireBatchUploads;Check(visible.SequenceEqual(Render(ed,view,rt,solid,false,false)),"Stationary crease flickers");Check(uploads==ed.WireBatchUploads,"Camera redraw uploads wire mesh");}Object.DestroyImmediate(mesh);Object.DestroyImmediate(doc);}report.AppendLine("PASS "+checks+" concave crease render checks");}catch(Exception e){exit=1;report.AppendLine(e.ToString());}finally{view.camera.targetTexture=null;Object.DestroyImmediate(view);Object.DestroyImmediate(rt);Object.DestroyImmediate(solid);}File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../crease-wire-result.txt")),report.ToString());EditorApplication.Exit(exit);}
}




